window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ee384a62df020ca6"]={"versions": [{"id": "FIG-ee384a62df020ca6", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Feature-Baum / Feature-Diagramm (FODA-basiertes Variabilitätsmodell) mit transversalen logischen Restriktionen (<em>Cross-Tree Constraints</em>).</li>\n<li><strong>Architektur-Kontext & Zweck:</strong> AUTOSAR Foundation (FO), Spezifikation <code>AUTOSAR_FO_RS_FeatureModelExchangeFormat</code> ([<code>UC_FMDT_00004</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/ee/ee384a62df020ca66e67e033a5fe533d4dd4162497ce1aeee799d6ee7bf3c531.webp)). Dient der werkzeugunabhängigen Modellierung und dem Austausch von Produktlinien-Variabilität (Software Product Line Engineering – SPLE) auf OEM-/Tier-1-Systemebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Entkoppelt orthogonale Feature-Dimensionen (z. B. Zielland vs. physische Lenkung vs. Kombiinstrument-Einheiten), um eine kombinatorische Explosion und Redundanz in der Baumhierarchie zu verhindern. Abhängigkeiten werden über separate aussagenlogische Restriktionen aufgelöst.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzelknoten (Root Feature):</strong></li>\n<li><code>Feature Model: Sample Car</code> (Top-Level-Systementität).</li>\n<li><strong>Pflicht-Feature-Gruppen (<code>Mandatory</code>, Multiplizität $[1..1]$ bezüglich Parent):</strong></li>\n<li><code>Mandatory: Country</code> (Zielmarkt).</li>\n<li><code>Mandatory: Steering Wheel</code> (Lenkradposition).</li>\n<li><code>Mandatory: Speedometer display</code> (Tachoanzeigeeinheit).</li>\n<li><strong>Kind-Features in XOR-Gruppen (<code>Alternative</code>, Multiplizität exakt 1 aus $N$ selektierbar):</strong></li>\n<li>Unter <code>Country</code>: <code>Alternative: Germany</code>, <code>Alternative: UK</code>, <code>Alternative: US</code>.</li>\n<li>Unter <code>Steering Wheel</code>: <code>Alternative: Left</code> (LHD), <code>Alternative: Right</code> (RHD).</li>\n<li>Unter <code>Speedometer display</code>: <code>Alternative: km/h</code>, <code>Alternative: mph</code>.</li>\n<li><strong>Transversale Restriktionen (Cross-Tree Constraints / Notiz-Elemente via gestrichelter Kanten):</strong></li>\n<li>$C_1$: $\\text{Left} \\implies (\\text{Germany} \\lor \\text{US})$</li>\n<li>$C_2$: $\\text{Right} \\implies \\text{UK}$</li>\n<li>$C_3$: $\\text{km/h} \\implies \\text{Germany}$</li>\n<li>$C_4$: $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Modellierungsartefakt:</strong> Kein Laufzeit-Sequenzablauf (keine RTE-/BSW-Tasks, keine PDUs, keine Callbacks).</li>\n<li><strong>Konfigurations- & Auflösungsprozess (Design-/Build-Time):</strong></li>\n<li><strong>Constraint-Satisfaction-Problem (CSP / SAT):</strong> Werkzeuge zur Variantenkonfiguration übergeben den Feature-Baum samt Restriktionsmatrix an einen SAT-Solver.</li>\n<li><strong>Auswertungssequenz:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bindung des Primärparameters (z. B. Selektion <code>Country == Germany</code>).</li>\n<li>Propagation der Constraints: $\\text{Germany}$ forciert $\\text{Steering Wheel} = \\text{Left}$ (da $\\text{Right} \\implies \\text{UK}$) und $\\text{Speedometer display} = \\text{km/h}$ (da $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$ und Auswahl von $\\text{km/h}$ mit $\\text{Germany}$ konsistent ist).</li>\n<li>Eine inkonsistente Selektion (z. B. <code>Germany</code> + <code>Right</code>) verletzt $C_2$ und führt zum Abbruch der Konfigurationsgenerierung (<em>Unfeasible Configuration Error</em>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>*<em>Bindungszeitpunkt (</em>Variation Binding Time<em>):</em>* Primär <code>System Definition Time</code> bzw. <code>Pre-Compile Time</code>.</li>\n<li><strong>Abbildung auf Classic/Adaptive AUTOSAR-Artefakte:</strong></li>\n<li>Das FMDT dient als vorgelagertes Modell für das <code>AUTOSAR_TPS_SystemTemplate</code>.</li>\n<li>Ausgewählte Features mappen direkt auf <code>VariationPoint</code>-Elemente in System Description, Software Component Description (SWCD) und BSW-Konfiguration (<code>EcucValueCollection</code>).</li>\n<li>Steuert bedingte Kompilierung (<code>#ifdef</code> via <code>Pre-Compile Time</code> Variation Switches) sowie die selektive Generierung von Runnables, Ports oder RTE-APIs.</li>\n<li><strong>Architektur-Richtlinie für Entwickler:</strong></li>\n<li>Variabilitäten niemals durch kaskadierte Sub-Bäume je Ländermarkt duplizieren.</li>\n<li>Orthogonale Domänen sauber trennen; Querverbindungen ausschließlich als minimale aussagenlogische Klauseln (<em>Requires</em> / <em>Excludes</em> bzw. Boole'sche Terme) im Feature-Modell definieren.</li>\n</ul>"}, {"id": "FIG-5d270a1504464274", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Feature-Baum / Feature-Diagramm (FODA-basiertes Variabilitätsmodell) mit transversalen logischen Restriktionen (<em>Cross-Tree Constraints</em>).</li>\n<li><strong>Architektur-Kontext & Zweck:</strong> AUTOSAR Foundation (FO), Spezifikation <code>AUTOSAR_FO_RS_FeatureModelExchangeFormat</code> ([<code>UC_FMDT_00004</code>](file:///Users/tobiasanton/.cache/autodocs/assets/figures/ee/ee384a62df020ca66e67e033a5fe533d4dd4162497ce1aeee799d6ee7bf3c531.webp)). Dient der werkzeugunabhängigen Modellierung und dem Austausch von Produktlinien-Variabilität (Software Product Line Engineering – SPLE) auf OEM-/Tier-1-Systemebene.</li>\n<li><strong>Funktionale Einordnung:</strong> Entkoppelt orthogonale Feature-Dimensionen (z. B. Zielland vs. physische Lenkung vs. Kombiinstrument-Einheiten), um eine kombinatorische Explosion und Redundanz in der Baumhierarchie zu verhindern. Abhängigkeiten werden über separate aussagenlogische Restriktionen aufgelöst.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzelknoten (Root Feature):</strong></li>\n<li><code>Feature Model: Sample Car</code> (Top-Level-Systementität).</li>\n<li><strong>Pflicht-Feature-Gruppen (<code>Mandatory</code>, Multiplizität $[1..1]$ bezüglich Parent):</strong></li>\n<li><code>Mandatory: Country</code> (Zielmarkt).</li>\n<li><code>Mandatory: Steering Wheel</code> (Lenkradposition).</li>\n<li><code>Mandatory: Speedometer display</code> (Tachoanzeigeeinheit).</li>\n<li><strong>Kind-Features in XOR-Gruppen (<code>Alternative</code>, Multiplizität exakt 1 aus $N$ selektierbar):</strong></li>\n<li>Unter <code>Country</code>: <code>Alternative: Germany</code>, <code>Alternative: UK</code>, <code>Alternative: US</code>.</li>\n<li>Unter <code>Steering Wheel</code>: <code>Alternative: Left</code> (LHD), <code>Alternative: Right</code> (RHD).</li>\n<li>Unter <code>Speedometer display</code>: <code>Alternative: km/h</code>, <code>Alternative: mph</code>.</li>\n<li><strong>Transversale Restriktionen (Cross-Tree Constraints / Notiz-Elemente via gestrichelter Kanten):</strong></li>\n<li>$C_1$: $\\text{Left} \\implies (\\text{Germany} \\lor \\text{US})$</li>\n<li>$C_2$: $\\text{Right} \\implies \\text{UK}$</li>\n<li>$C_3$: $\\text{km/h} \\implies \\text{Germany}$</li>\n<li>$C_4$: $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Modellierungsartefakt:</strong> Kein Laufzeit-Sequenzablauf (keine RTE-/BSW-Tasks, keine PDUs, keine Callbacks).</li>\n<li><strong>Konfigurations- & Auflösungsprozess (Design-/Build-Time):</strong></li>\n<li><strong>Constraint-Satisfaction-Problem (CSP / SAT):</strong> Werkzeuge zur Variantenkonfiguration übergeben den Feature-Baum samt Restriktionsmatrix an einen SAT-Solver.</li>\n<li><strong>Auswertungssequenz:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bindung des Primärparameters (z. B. Selektion <code>Country == Germany</code>).</li>\n<li>Propagation der Constraints: $\\text{Germany}$ forciert $\\text{Steering Wheel} = \\text{Left}$ (da $\\text{Right} \\implies \\text{UK}$) und $\\text{Speedometer display} = \\text{km/h}$ (da $\\text{mph} \\implies (\\text{UK} \\lor \\text{US})$ und Auswahl von $\\text{km/h}$ mit $\\text{Germany}$ konsistent ist).</li>\n<li>Eine inkonsistente Selektion (z. B. <code>Germany</code> + <code>Right</code>) verletzt $C_2$ und führt zum Abbruch der Konfigurationsgenerierung (<em>Unfeasible Configuration Error</em>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>*<em>Bindungszeitpunkt (</em>Variation Binding Time<em>):</em>* Primär <code>System Definition Time</code> bzw. <code>Pre-Compile Time</code>.</li>\n<li><strong>Abbildung auf Classic/Adaptive AUTOSAR-Artefakte:</strong></li>\n<li>Das FMDT dient als vorgelagertes Modell für das <code>AUTOSAR_TPS_SystemTemplate</code>.</li>\n<li>Ausgewählte Features mappen direkt auf <code>VariationPoint</code>-Elemente in System Description, Software Component Description (SWCD) und BSW-Konfiguration (<code>EcucValueCollection</code>).</li>\n<li>Steuert bedingte Kompilierung (<code>#ifdef</code> via <code>Pre-Compile Time</code> Variation Switches) sowie die selektive Generierung von Runnables, Ports oder RTE-APIs.</li>\n<li><strong>Architektur-Richtlinie für Entwickler:</strong></li>\n<li>Variabilitäten niemals durch kaskadierte Sub-Bäume je Ländermarkt duplizieren.</li>\n<li>Orthogonale Domänen sauber trennen; Querverbindungen ausschließlich als minimale aussagenlogische Klauseln (<em>Requires</em> / <em>Excludes</em> bzw. Boole'sche Terme) im Feature-Modell definieren.</li>\n</ul>"}], "trans": [{"from": "FIG-ee384a62df020ca6", "to": "FIG-5d270a1504464274", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
